package stream
import ("bytes"; "fmt"; "io"; "testing")
type zzEOFReader struct { *bytes.Reader }
func (r zzEOFReader) ReadAt(p []byte, off int64) (int, error) {
 n, err := r.Reader.ReadAt(p, off)
 if off+int64(n) == r.Size() { err = io.EOF }
 return n, err
}
func TestZZProbe(t *testing.T) {
 key := make([]byte, 32)
 var ciphertext bytes.Buffer
 w, err := NewEncryptWriter(key, &ciphertext)
 if err != nil { t.Fatal(err) }
 if _, err := w.Write([]byte("hello")); err != nil { t.Fatal(err) }
 if err := w.Close(); err != nil { t.Fatal(err) }
 _, err = NewDecryptReaderAt(key, zzEOFReader{bytes.NewReader(ciphertext.Bytes())}, int64(ciphertext.Len()))
 if err != nil { fmt.Println("probe: error") } else { fmt.Println("probe: ok") }
}
EOF
